import{_ as e,c as a,o as n,a0 as i}from"./chunks/framework.DKRgXLPU.js";const l=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"nl/blog/elite-goal-setting.md","filePath":"nl/blog/elite-goal-setting.md"}');const t=e({name:"nl/blog/elite-goal-setting.md"},[["render",function(e,l,t,o,r,s){return n(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="doelstellingen-formuleren-voor-topsporters" tabindex="-1">Doelstellingen formuleren voor topsporters <a class="header-anchor" href="#doelstellingen-formuleren-voor-topsporters" aria-label="Permalink to &quot;Doelstellingen formuleren voor topsporters&quot;">​</a></h1><p>Doelstellingen formuleren lijkt eenvoudig: bepaal wat je wilt en werk ernaartoe. Maar doelstellingen formuleren op topniveau is complexer. De juiste doelen versnellen de ontwikkeling; de verkeerde leiden tot frustratie en stagnatie.</p><h2 id="voorbij-de-basisdoelen" tabindex="-1">Voorbij de basisdoelen <a class="header-anchor" href="#voorbij-de-basisdoelen" aria-label="Permalink to &quot;Voorbij de basisdoelen&quot;">​</a></h2><p>De meeste spelers stellen resultaatdoelen: &quot;Het regionale kampioenschap winnen.&quot; Deze doelen brengen echter problemen met zich mee:</p><ul><li>Je kunt de uitkomsten niet volledig beheersen.</li><li>Ze creëren druk zonder richting te geven.</li><li>Succes of mislukking is binair.</li><li>Ze bieden geen leidraad voor de dagelijkse praktijk.</li></ul><p>Het stellen van topdoelen gaat verder dan dat.</p><h2 id="de-doelhierarchie" tabindex="-1">De doelhiërarchie <a class="header-anchor" href="#de-doelhierarchie" aria-label="Permalink to &quot;De doelhiërarchie&quot;">​</a></h2><h3 id="niveau-1-droomdoelen-1-5-jaar" tabindex="-1">Niveau 1: Droomdoelen (1-5 jaar) <a class="header-anchor" href="#niveau-1-droomdoelen-1-5-jaar" aria-label="Permalink to &quot;Niveau 1: Droomdoelen (1-5 jaar)&quot;">​</a></h3><p>Jouw ultieme ambities:</p><ul><li>&quot;Deelnemen aan wedstrijden op nationaal niveau&quot;</li><li>&quot;Word erkend als een topschutter&quot;</li><li>&quot;Win een belangrijk kampioenschap&quot;</li></ul><p>Deze bieden richting en motivatie, maar zijn niet dagelijks in de praktijk te brengen.</p><h3 id="niveau-2-prestatiedoelen-seizoen-jaar" tabindex="-1">Niveau 2: Prestatiedoelen (Seizoen/Jaar) <a class="header-anchor" href="#niveau-2-prestatiedoelen-seizoen-jaar" aria-label="Permalink to &quot;Niveau 2: Prestatiedoelen (Seizoen/Jaar)&quot;">​</a></h3><p>Meetbare verbeteringen in je spel:</p><ul><li>&quot;Verhoog de schietnauwkeurigheid van 60% naar 70%&quot;</li><li>&quot;Verminder onnodige fouten met 25%&quot;</li><li>&quot;Ontwikkel een betrouwbare plombée&quot;</li></ul><p>Deze zaken heb je zelf in de hand en zijn meetbaar.</p><h3 id="niveau-3-procesdoelen-dagelijks-wekelijks" tabindex="-1">Niveau 3: Procesdoelen (dagelijks/wekelijks) <a class="header-anchor" href="#niveau-3-procesdoelen-dagelijks-wekelijks" aria-label="Permalink to &quot;Niveau 3: Procesdoelen (dagelijks/wekelijks)&quot;">​</a></h3><p>De acties die tot verbetering leiden:</p><ul><li>&quot;Voltooi elke worp vóór de worp&quot;</li><li>&quot;Oefen dagelijks 10 minuten met visualisatie.&quot;</li><li>&quot;Train je schiettechniek 3 keer per week&quot;</li></ul><p>Deze zijn volledig beheersbaar en dragen bij aan het behalen van prestatiedoelen.</p><h2 id="het-smart-raamwerk" tabindex="-1">Het SMART+ raamwerk <a class="header-anchor" href="#het-smart-raamwerk" aria-label="Permalink to &quot;Het SMART+ raamwerk&quot;">​</a></h2><p>Ga verder dan de basis SMART-doelen:</p><h3 id="specifiek" tabindex="-1">Specifiek <a class="header-anchor" href="#specifiek" aria-label="Permalink to &quot;Specifiek&quot;">​</a></h3><p>Niet &quot;mijn richtvermogen verbeteren&quot;, maar &quot;een consistente demi-portée ontwikkelen waarmee ik vanaf 8 meter binnen 30 cm van het doel kan landen.&quot;</p><h3 id="meetbaar" tabindex="-1">Meetbaar <a class="header-anchor" href="#meetbaar" aria-label="Permalink to &quot;Meetbaar&quot;">​</a></h3><p>Bepaal hoe je de voortgang zult bijhouden:</p><ul><li>Succespercentages</li><li>Consistentiemetrieken</li><li>Videoanalyse-markers</li></ul><h3 id="haalbaar-maar-wel-een-uitdaging" tabindex="-1">Haalbaar, maar wel een uitdaging. <a class="header-anchor" href="#haalbaar-maar-wel-een-uitdaging" aria-label="Permalink to &quot;Haalbaar, maar wel een uitdaging.&quot;">​</a></h3><p>Het doel moet groei vereisen, maar wel realistisch zijn. Een schutter met een schotpercentage van 60% die streeft naar 65% is haalbaar; streven naar 90% is pure fantasie.</p><h3 id="relevant" tabindex="-1">Relevant <a class="header-anchor" href="#relevant" aria-label="Permalink to &quot;Relevant&quot;">​</a></h3><p>Doelen moeten aansluiten bij je grotere ambities en daadwerkelijke zwakke punten aanpakken, niet alleen zaken die makkelijk te verbeteren zijn.</p><h3 id="tijdsgebonden" tabindex="-1">Tijdsgebonden <a class="header-anchor" href="#tijdsgebonden" aria-label="Permalink to &quot;Tijdsgebonden&quot;">​</a></h3><p>Stel duidelijke deadlines vast:</p><ul><li>&quot;Tegen het einde van het seizoen&quot;</li><li>&quot;Binnen 3 maanden&quot;</li><li>&quot;Door het nationale kampioenschap&quot;</li></ul><h3 id="persoonlijk-betekenisvol" tabindex="-1">+ Persoonlijk betekenisvol <a class="header-anchor" href="#persoonlijk-betekenisvol" aria-label="Permalink to &quot;+ Persoonlijk betekenisvol&quot;">​</a></h3><p>Het doel moet voor JOU belangrijk zijn, niet alleen voor je coach of teamgenoten. Innerlijke motivatie zorgt ervoor dat je volhoudt, ook als de vooruitgang traag is.</p><h2 id="focus-op-het-proces-versus-focus-op-het-resultaat" tabindex="-1">Focus op het proces versus focus op het resultaat <a class="header-anchor" href="#focus-op-het-proces-versus-focus-op-het-resultaat" aria-label="Permalink to &quot;Focus op het proces versus focus op het resultaat&quot;">​</a></h2><h3 id="het-probleem-met-resultaatgerichte-doelen" tabindex="-1">Het probleem met resultaatgerichte doelen <a class="header-anchor" href="#het-probleem-met-resultaatgerichte-doelen" aria-label="Permalink to &quot;Het probleem met resultaatgerichte doelen&quot;">​</a></h3><p>&quot;De wedstrijd winnen&quot; leidt tot problemen:</p><ul><li>Angst voor dingen waar je geen controle over hebt.</li><li>Afleiding van de uitvoering</li><li>Alles-of-niets-denken</li><li>Druk uitoefenen zonder begeleiding</li></ul><h3 id="de-kracht-van-procesdoelen" tabindex="-1">De kracht van procesdoelen <a class="header-anchor" href="#de-kracht-van-procesdoelen" aria-label="Permalink to &quot;De kracht van procesdoelen&quot;">​</a></h3><p>&quot;Voer mijn voorbereidingsroutine perfect uit&quot; biedt:</p><ul><li>Volledige controle</li><li>Duidelijke focus</li><li>Directe feedback</li><li>Bouwt op natuurlijke wijze toe naar resultaten.</li></ul><h3 id="de-balans" tabindex="-1">De balans <a class="header-anchor" href="#de-balans" aria-label="Permalink to &quot;De balans&quot;">​</a></h3><p>Gebruik resultaatdoelen voor motivatie en richting. Gebruik procesdoelen voor dagelijkse focus en uitvoering.</p><h2 id="doelstellingen-formuleren-voor-verschillende-fasen" tabindex="-1">Doelstellingen formuleren voor verschillende fasen <a class="header-anchor" href="#doelstellingen-formuleren-voor-verschillende-fasen" aria-label="Permalink to &quot;Doelstellingen formuleren voor verschillende fasen&quot;">​</a></h2><h3 id="buiten-het-seizoen" tabindex="-1">Buiten het seizoen <a class="header-anchor" href="#buiten-het-seizoen" aria-label="Permalink to &quot;Buiten het seizoen&quot;">​</a></h3><p>Focus op ontwikkelingsdoelen:</p><ul><li>Technische verbeteringen</li><li>Fysieke conditie</li><li>Het ontwikkelen van mentale vaardigheden</li><li>Je assortiment plaids uitbreiden</li></ul><h3 id="voorseizoen" tabindex="-1">Voorseizoen <a class="header-anchor" href="#voorseizoen" aria-label="Permalink to &quot;Voorseizoen&quot;">​</a></h3><p>Overgang naar integratie:</p><ul><li>Het combineren van vaardigheden onder wedstrijdomstandigheden.</li><li>Testen van verbeteringen in vriendschappelijke competitie</li><li>Verfijningsstrategieën</li></ul><h3 id="wedstrijdseizoen" tabindex="-1">Wedstrijdseizoen <a class="header-anchor" href="#wedstrijdseizoen" aria-label="Permalink to &quot;Wedstrijdseizoen&quot;">​</a></h3><p>Schakel over naar prestaties en processen:</p><ul><li>Het uitvoeren van wat je hebt ontwikkeld</li><li>Doelstellingen voor het proces bij elke wedstrijd</li><li>Minimale technische wijzigingen</li></ul><h3 id="na-de-wedstrijd" tabindex="-1">Na de wedstrijd <a class="header-anchor" href="#na-de-wedstrijd" aria-label="Permalink to &quot;Na de wedstrijd&quot;">​</a></h3><p>Reflectie en planning:</p><ul><li>Analyseer wat wel werkte</li><li>Identificeer groeimogelijkheden.</li><li>Stel doelen voor de volgende cyclus</li></ul><h2 id="veelvoorkomende-fouten-bij-het-stellen-van-doelen" tabindex="-1">Veelvoorkomende fouten bij het stellen van doelen <a class="header-anchor" href="#veelvoorkomende-fouten-bij-het-stellen-van-doelen" aria-label="Permalink to &quot;Veelvoorkomende fouten bij het stellen van doelen&quot;">​</a></h2><h3 id="te-veel-doelen" tabindex="-1">Te veel doelen <a class="header-anchor" href="#te-veel-doelen" aria-label="Permalink to &quot;Te veel doelen&quot;">​</a></h3><p>Focus is kracht. 2-3 kerndoelen zijn beter dan 10 verspreide doelen.</p><h3 id="alleen-resultaatgerichte-doelen" tabindex="-1">Alleen resultaatgerichte doelen <a class="header-anchor" href="#alleen-resultaatgerichte-doelen" aria-label="Permalink to &quot;Alleen resultaatgerichte doelen&quot;">​</a></h3><p>Zonder procesdoelen heb je geen routekaart.</p><h3 id="geen-flexibiliteit" tabindex="-1">Geen flexibiliteit <a class="header-anchor" href="#geen-flexibiliteit" aria-label="Permalink to &quot;Geen flexibiliteit&quot;">​</a></h3><p>Doelstellingen moeten zich aanpassen aan nieuwe informatie. Het star vasthouden aan verouderde doelstellingen is verspilling van inspanning.</p><h3 id="doelstellingen-gebaseerd-op-vergelijking" tabindex="-1">Doelstellingen gebaseerd op vergelijking <a class="header-anchor" href="#doelstellingen-gebaseerd-op-vergelijking" aria-label="Permalink to &quot;Doelstellingen gebaseerd op vergelijking&quot;">​</a></h3><p>&quot;Wees beter dan [speler]&quot; legt je succes in de handen van iemand anders.</p><h3 id="mentale-doelen-verwaarlozen" tabindex="-1">Mentale doelen verwaarlozen <a class="header-anchor" href="#mentale-doelen-verwaarlozen" aria-label="Permalink to &quot;Mentale doelen verwaarlozen&quot;">​</a></h3><p>Technische en fysieke doelen staan centraal, maar mentale vaardigheden bepalen vaak wie er wint.</p><h2 id="implementatiestrategieen" tabindex="-1">Implementatiestrategieën <a class="header-anchor" href="#implementatiestrategieen" aria-label="Permalink to &quot;Implementatiestrategieën&quot;">​</a></h2><h3 id="schrijf-ze-op" tabindex="-1">Schrijf ze op. <a class="header-anchor" href="#schrijf-ze-op" aria-label="Permalink to &quot;Schrijf ze op.&quot;">​</a></h3><p>Het is aanzienlijk waarschijnlijker dat schriftelijk vastgelegde doelen worden bereikt.</p><h3 id="regelmatig-evalueren" tabindex="-1">Regelmatig evalueren <a class="header-anchor" href="#regelmatig-evalueren" aria-label="Permalink to &quot;Regelmatig evalueren&quot;">​</a></h3><p>Een wekelijkse evaluatie houdt de doelen scherp en maakt bijsturing mogelijk.</p><h3 id="deel-selectief" tabindex="-1">Deel selectief <a class="header-anchor" href="#deel-selectief" aria-label="Permalink to &quot;Deel selectief&quot;">​</a></h3><p>Deel dit met mensen die je zullen steunen, niet ondermijnen.</p><h3 id="visualiseer-je-prestaties" tabindex="-1">Visualiseer je prestaties <a class="header-anchor" href="#visualiseer-je-prestaties" aria-label="Permalink to &quot;Visualiseer je prestaties&quot;">​</a></h3><p>Stel je regelmatig voor dat je je doelen bereikt – het gevoel, het moment.</p><h3 id="voortgang-bijhouden" tabindex="-1">Voortgang bijhouden <a class="header-anchor" href="#voortgang-bijhouden" aria-label="Permalink to &quot;Voortgang bijhouden&quot;">​</a></h3><p>Wat gemeten wordt, kan beheerd worden. Houd gegevens bij.</p><h2 id="wanneer-doelen-niet-worden-bereikt" tabindex="-1">Wanneer doelen niet worden bereikt <a class="header-anchor" href="#wanneer-doelen-niet-worden-bereikt" aria-label="Permalink to &quot;Wanneer doelen niet worden bereikt&quot;">​</a></h2><p>Niet behaalde doelen zijn geen mislukkingen, maar data:</p><ol><li><strong>Analyseer</strong>: Waarom is het niet gelukt?</li><li><strong>Wat leer je hiervan?</strong></li><li><strong>Aanpassen</strong>: Het doel of de aanpak wijzigen</li><li><strong>Vervolg</strong>: Volharding wint van perfectie</li></ol><h2 id="het-mentale-spel-van-doelpunten" tabindex="-1">Het mentale spel van doelpunten <a class="header-anchor" href="#het-mentale-spel-van-doelpunten" aria-label="Permalink to &quot;Het mentale spel van doelpunten&quot;">​</a></h2><p>Doelen beïnvloeden de psychologie:</p><ul><li><strong>Te makkelijk</strong>: Verveling, zelfgenoegzaamheid</li><li><strong>Te moeilijk</strong>: Angst, ontmoediging</li><li><strong>Precies goed</strong>: Betrokkenheid, flow, groei</li></ul><p>Vind de ideale balans waarbij doelen uitdagend zijn zonder overweldigend te werken.</p><hr><p>| <em>Gerelateerd: <a href="/en/education/goals/">Inleiding tot het stellen van doelen</a> | <a href="/en/education/goals/smart-goals">SMART-doelen</a> | <a href="/en/education/goals/planning">Je ontwikkeling plannen</a></em> |</p>',88)])])}]]);export{l as __pageData,t as default};
